[{"order":1,"type":"heading","text":"Custom Stores and Contract Patterns in Svelte"},{"order":2,"type":"paragraph","text":"Svelte stores provide a powerful mechanism for reactive state management. While the built-in writable, readable, and derived stores cover most use cases, complex applications often require domain-specific logic and strict adherence to specific interfaces, known as contract patterns."},{"order":3,"type":"subheading","text":"Understanding the Store Contract"},{"order":4,"type":"paragraph","text":"In Svelte, a store is simply an object that implements the store contract. This contract requires a 'subscribe' method. The subscribe method takes a run function as an argument and immediately calls it with the current value of the store. It returns an unsubscribe function to clean up the subscription."},{"order":5,"type":"bullet_point","text":"subscribe(run: (value: T) => void): () => void"},{"order":6,"type":"bullet_point","text":"Optional: set(value: T) => void (typically for writable stores)"},{"order":7,"type":"bullet_point","text":"Optional: update(updater: (value: T) => T) => void (typically for writable stores)"},{"order":8,"type":"subheading","text":"Building a Custom Store with Encapsulated Logic"},{"order":9,"type":"paragraph","text":"By wrapping internal writable stores, we can expose only the methods that are relevant to our business logic, effectively implementing a strict contract and preventing unauthorized state mutations from external components."},{"order":10,"type":"code","text":"import { writable } from 'svelte/store';

export function createCounter() {
  const { subscribe, set, update } = writable(0);

  return {
    subscribe,
    increment: () => update(n => n + 1),
    decrement: () => update(n => n - 1),
    reset: () => set(0)
  };
}"},{"order":11,"type":"subheading","text":"Implementing Contract Patterns for Async Operations"},{"order":12,"type":"paragraph","text":"Custom stores shine when managing asynchronous workflows like data fetching. We can establish a robust contract that handles loading states, error handling, and data caching natively within the store abstraction."},{"order":13,"type":"code","text":"import { writable } from 'svelte/store';

export function createResourceStore(fetchFunction) {
  const { subscribe, set, update } = writable({
    data: null,
    loading: false,
    error: null
  });

  return {
    subscribe,
    load: async (...args) => {
      update(state => ({ ...state, loading: true, error: null }));
      try {
        const data = await fetchFunction(...args);
        set({ data, loading: false, error: null });
      } catch (error) {
        update(state => ({ ...state, loading: false, error }));
      }
    }
  };
}"},{"order":14,"type":"subheading","text":"Consuming Custom Stores in Svelte Components"},{"order":15,"type":"paragraph","text":"Using custom stores in Svelte components follows the standard auto-subscription syntax using the '$' prefix. Because our custom store adheres to the store contract, Svelte seamlessly handles subscriptions behind the scenes."},{"order":16,"type":"code","text":"<script>
  import { createCounter } from './counterStore';

  const counter = createCounter();
</script>

<p>Count: {$counter}</p>
<button on:click={counter.increment}>+</button>
<button on:click={counter.decrement}>-</button>
<button on:click={counter.reset}>Reset</button>"}]
